        List<Map<String, Object>> items = new ArrayList<>();
        items.add(reserveItem(uniqueKey("RSV"), ev1, "BENCH-A", utc(11, 0), utc(10, 0)));
        items.add(reserveItem(uniqueKey("RSV"), ev2, "BENCH-A", utc(10, 0), utc(11, 0)));
