        // 诊断窗口非法返回 400；未知台位返回 404。
        assertThat(occupancy("BENCH-A", utc(11, 0), utc(11, 0)).getResponse().getStatus())
                .isEqualTo(400);
        assertThat(occupancy("BENCH-X", utc(10, 0), utc(11, 0)).getResponse().getStatus())
                .isEqualTo(404);
    }

